  "<!doctype html><meta charset=\"utf-8\"><title>共议管理面板</title><p style=\"font:15px system-ui;padding:40px\">请从任务栏的共议图标打开管理面板。</p>": "<!doctype html><meta charset=\"utf-8\"><title>CoDiscuss admin panel</title><p style=\"font:15px system-ui;padding:40px\">Open the admin panel from the CoDiscuss tray icon.</p>",
